script:
// Flight Readout: a small extra HUD with TWR, vertical speed, apoapsis/periapsis, Mach, dynamic pressure and heat.
let panel = null, shown = api.storage.get('shown') !== false, acc = 0;
function make() {
  panel = api.ui.panel('readout');
  panel.style.cssText = 'left:calc(8px + var(--sal));top:calc(50px + var(--sat));padding:6px 9px;border-radius:10px;background:rgba(10,15,26,0.62);border:1px solid rgba(160,200,255,0.25);font:11px/1.45 system-ui,sans-serif;color:#cfe3ff;font-variant-numeric:tabular-nums;min-width:104px';
  panel.style.display = shown ? '' : 'none';
}
const row = (k, v, warn) => `<div style="display:flex;justify-content:space-between;gap:8px"><span style="opacity:.65">${k}</span><b style="color:${warn ? '#ffb14a' : '#fff'}">${v}</b></div>`;
api.onFlightStart(() => make());
api.onUpdate((dt, f) => {
  if (!f) return;
  if (!panel || !panel.isConnected) make();
  acc += dt; if (acc < 0.2) return; acc = 0;
  if (!shown) return;
  const km = m => !isFinite(m) ? '—' : Math.abs(m) >= 1e6 ? (m / 1e6).toFixed(2) + ' Mm' : (m / 1000).toFixed(1) + ' km';
  panel.innerHTML = row('TWR', f.twr.toFixed(2), f.twr > 0 && f.twr < 1)
    + row('V/S', f.vSpeed.toFixed(0) + ' m/s', f.vSpeed < -50 && f.radar < 2000)
    + row('Ap', km(f.ap)) + row('Pe', km(f.pe), f.pe < 0)
    + row('Mach', f.mach.toFixed(2)) + row('Q', f.q.toFixed(1) + ' kPa', f.q > 30)
    + row('Heat', Math.round(f.heat * 100) + '%', f.heat > 0.7)
    + row('MET', new Date(Math.max(0, f.met) * 1000).toISOString().substr(11, 8));
});
api.addUIButton({ label: 'Readout', icon: '📟', where: 'flight', onClick: () => { shown = !shown; api.storage.set('shown', shown); if (panel) panel.style.display = shown ? '' : 'none'; api.toast('Flight readout ' + (shown ? 'on' : 'off'), 1200); } });
